368	
369	type SortKey = 'name' | 'responseTime' | 'gamesPlayed';
370	type SortDirection = 'asc' | 'desc';
371	
372	const compareNullableNumber = (
373	    a: number | null | undefined,
374	    b: number | null | undefined,
375	    direction: SortDirection,
376	) => {
377	    if (a == null && b == null) return 0;
378	    if (a == null) return 1;
379	    if (b == null) return -1;
380	    return direction === 'asc' ? a - b : b - a;
381	};
382	
383	const compareNullableString = (
384	    a: string | null | undefined,
385	    b: string | null | undefined,
386	    direction: SortDirection,
387	) => {
388	    if (a == null && b == null) return 0;
389	    if (a == null) return 1;
390	    if (b == null) return -1;
391	    const result = a.localeCompare(b);
392	    return direction === 'asc' ? result : -result;
393	};
394	
395	const formatResponseInterval = (seconds: number | null | undefined) => {
396	    if (seconds == null) return '-';
397	    if (seconds < 60) return `${seconds}s`;
398	
399	    const minutes = Math.floor(seconds / 60);
400	    if (minutes < 60) return `${minutes}m`;
401	
402	    const hours = Math.floor(minutes / 60);
403	    const remainingMinutes = minutes % 60;
404	    if (hours < 24) {
405	        return remainingMinutes ? `${hours}h ${remainingMinutes}m` : `${hours}h`;
406	    }
407	
408	    const days = Math.floor(hours / 24);
409	    const remainingHours = hours % 24;
410	    return remainingHours ? `${days}d ${remainingHours}h` : `${days}d`;
411	};
412	
413	const getPlayerName = (row: PickerPlayerType) => row.player.name ?? `Player ${row.playerId}`;
414	
415	const buildDefaultSelection = (rows: PickerPlayerType[], maxSelected = 12) => {
416	    if (!rows.length) return [];
417	    const sorted = [...rows].sort((a, b) => {
418	        const responseCompare = compareNullableNumber(a.responseInterval, b.responseInterval, 'asc');
419	        if (responseCompare !== 0) return responseCompare;
420	        const nameCompare = compareNullableString(a.player.name, b.player.name, 'asc');
421	        if (nameCompare !== 0) return nameCompare;
422	        return a.playerId - b.playerId;
423	    });
424	    return sorted.slice(0, maxSelected).map((row) => row.playerId);
425	};
