80	    setSubmittingPlayerId: React.Dispatch<React.SetStateAction<number | null>>;
81	}
82	
83	const DebtRow = ({
84	    row,
85	    payDebt,
86	    submittingPlayerId,
87	    setSubmittingPlayerId,
88	}: DebtRowProps) => {
89	    const router = useRouter();
90	    const totalDebt = row.debts.reduce((sum, d) => sum + d.amount, 0);
91	
92	    const form = useForm<PayDebtFormValues>({
93	        initialValues: {
94	            checkedIds: row.debts.map((d) => d.gameDay.id),
95	        },
96	        validate: zod4Resolver(PayDebtFormSchema),
97	    });
98	
99	    const checkedDebts = row.debts.filter((d) => form.values.checkedIds.includes(d.gameDay.id));
100	    const totalAmount = checkedDebts.reduce((sum, d) => sum + d.amount, 0);
101	
102	    const toggleDebt = (gameDayId: number) => {
103	        const current = form.values.checkedIds;
104	        form.setFieldValue(
105	            'checkedIds',
106	            current.includes(gameDayId) ?
107	                current.filter((id) => id !== gameDayId) :
108	                [...current, gameDayId],
109	        );
110	    };
111	
112	    const handlePay = async (values: PayDebtFormValues) => {
113	        const notificationId = `money-paid-${row.player.id}`;
114	        const gameDayIds = values.checkedIds;
115	        const amount = row.debts
116	            .filter((d) => gameDayIds.includes(d.gameDay.id))
117	            .reduce((sum, d) => sum + d.amount, 0);
118	
119	        const payload: PayDebtInput = {
120	            playerId: row.player.id,
121	            amount,
122	            gameDayIds,
123	        };
124	
125	        notifications.show({
126	            id: notificationId,
127	            loading: true,
128	            title: 'Recording payment',
129	            message: `Recording ${formatCurrency(amount)} for ${row.player.name ?? 'player'} across ${gameDayIds.length} game(s)...`,
130	            autoClose: false,
131	            withCloseButton: false,
132	        });
133	
134	        setSubmittingPlayerId(row.player.id);
135	        try {
136	            const result = await payDebt(payload);
137	
138	            notifications.update({
139	                id: notificationId,
140	                color: 'teal',
141	                title: 'Payment recorded',
142	                message: `Created ${result.transactionIds.length} transaction(s). New balance: ${formatCurrencySigned(result.resultingBalance)}.`,
143	                icon: <IconCheck size={config.notificationIconSize} />,
144	                loading: false,
145	                autoClose: config.notificationAutoClose,
146	            });
147	
148	            router.refresh();
149	        } catch (error) {
150	            captureUnexpectedError(error, {
151	                layer: 'client',
152	                component: 'MoneyForm',
153	                action: 'payDebt',
154	                route: '/footy/admin/money',
155	                extra: {
156	                    playerId: row.player.id,
157	                    amount,
158	                    gameDayCount: gameDayIds.length,
159	                },
160	            });
161	            const message = error instanceof Error ? error.message : 'Failed to record payment';
162	            notifications.update({
163	                id: notificationId,
164	                color: 'red',
165	                title: 'Error',
166	                message,
167	                icon: <IconAlertTriangle size={config.notificationIconSize} />,
168	                loading: false,
169	                autoClose: false,
170	                withCloseButton: true,
171	            });
172	        } finally {
173	            setSubmittingPlayerId(null);
174	        }
175	    };
176	
177	    return (
178	        <Box
179	            component="form"
180	            onSubmit={form.onSubmit(handlePay)}
181	            bd="1px solid var(--mantine-color-gray-3)"
182	            p="sm"
183	            bdrs="sm"
184	        >
185	            <Stack gap="sm">
186	                <Group wrap="nowrap">
187	                    <Anchor href={`/footy/player/${row.player.id}`}>
188	                        <Image
189	                            w={48}
190	                            h={48}
191	                            radius="xl"
192	                            src={`/api/footy/player/${row.player.id}/mugshot`}
193	                            alt={row.player.name ?? `Player ${row.player.id}`}
194	                        />
195	                    </Anchor>
196	                    <Stack gap={0} style={{ flex: 1, minWidth: 0 }}>
197	                        <Anchor href={`/footy/player/${row.player.id}`}>
198	                            {row.player.name ?? `Player ${row.player.id}`}
199	                        </Anchor>
200	                        <Text size="sm" c={getBalanceColor(-totalDebt)}>
201	                            Total debt: {formatCurrencySigned(-totalDebt)} ({row.debts.length} game{row.debts.length === 1 ? '' : 's'})
202	                        </Text>
203	                    </Stack>
204	                </Group>
205	
206	                {row.debts.length > 0 && (
207	                    <Stack gap="xs">
208	                        {row.debts.map((debt) => (
209	                            <Checkbox
