212	                                onChange={() => toggleDebt(debt.gameDay.id)}
213	                                label={
214	                                    <Group gap="xs">
215	                                        <GameDayLink gameDay={debt.gameDay} />
216	                                        <Text size="sm">{formatCurrency(debt.amount)}</Text>
217	                                    </Group>
218	                                }
219	                            />
220	                        ))}
221	                    </Stack>
222	                )}
223	
224	                <Group wrap="nowrap" justify="flex-end">
225	                    <Text size="sm" fw={500}>
226	                        {formatCurrency(totalAmount)}
227	                    </Text>
228	                    <Button
229	                        type="submit"
230	                        disabled={form.values.checkedIds.length === 0 || submittingPlayerId === row.player.id}
231	                        loading={submittingPlayerId === row.player.id}
