70	    const canonicalUrl = `/footy/table/${table}${canonicalSearch}`;
71	    const currentSearch = resolvedSearchParams?.year ? `?year=${resolvedSearchParams.year}` : '';
72	    const currentUrl = `/footy/table/${table}${currentSearch}`;
