24	/**
25	 * Asynchronously unpacks and validates search parameters for the footy games
26	 * page, fetching relevant data such as available years, the current game day,
27	 * and game statistics.
28	 *
29	 * - Validates the `year` parameter from the search params, ensuring it is a
30	 *   valid year present in the list of all years.
31	 * - If the year is invalid or missing, triggers a 404 not found response.
32	 * - Fetches the number of games played, cancelled, and remaining for the
33	 *   specified year.
34	 * - Ensures the canonical URL structure by redirecting if the current URL does
35	 *   not match the canonical format.
36	 * - Constructs a title and subhead string summarizing the games data.
37	 *
38	 * @param searchParams - The search parameters from the page props, expected to
39	 * include a `year` query parameter.
40	 * @returns An object containing the validated year, all available years, the
41	 * current game day, a title, and a subhead string.
42	 * @throws Redirects to the canonical URL if the current URL is not canonical.
43	 * @throws Triggers a 404 not found response if the year is invalid or not
44	 * present in the available years.
45	 */
46	const unpackParams = cache(async (
47	    searchParams: PageProps['searchParams'],
48	) => {
49	    const [resolvedSearchParams, allYears, currentGameDay] = await Promise.all([
50	        searchParams,
51	        gameDayService.getAllYears({
52	            includeAllTime: true,
53	            mostRecentFirst: true,
54	        }),
55	        gameDayService.getCurrent(),
56	    ]);
57	    const yearResult = z.coerce.number().int().min(0).safeParse(resolvedSearchParams?.year ?? 0);
58	    const year = yearResult.success ? yearResult.data : undefined;
59	    if (year === undefined || !allYears.includes(year)) notFound();
60	
61	    const [gamesPlayed, gamesCancelled, gamesRemaining] = await Promise.all([
62	        gameDayService.getGamesPlayed(year, currentGameDay?.id),
63	        gameDayService.getGamesCancelled(year, currentGameDay?.id),
64	        gameDayService.getGamesRemaining(year),
65	    ]);
66	
67	    /* v8 ignore next -- year is always defined here; the notFound() guard above already excludes undefined */
68	    const canonicalSearch = year !== undefined ? `?year=${year}` : '';
69	    const canonicalUrl = `/footy/games/${canonicalSearch}`;
70	    const currentSearch = resolvedSearchParams?.year !== undefined ?
71	        `?year=${resolvedSearchParams.year}` :
72	        '';
73	    const currentUrl = `/footy/games/${currentSearch}`;
74	    if (currentUrl !== canonicalUrl) permanentRedirect(canonicalUrl);
75	
76	    const title = `${year ? `${year} ` : ''}Games`;
77	    const subheadValues = [];
78	    if (gamesPlayed) subheadValues.push(`${gamesPlayed} played`);
79	    if (gamesCancelled) subheadValues.push(`${gamesCancelled} cancelled`);
80	    if (gamesRemaining) subheadValues.push(`${gamesRemaining} confirmed`);
81	    const subhead = subheadValues.join(', ');
82	
83	    return { year, allYears, currentGameDay, title, subhead };
84	});
